#!/usr/bin/env -S uv run --script
# Synced from bootstrap: repo/tools/git/tasks/git-merge-main.py. Do not edit this file.
# The next sync writes it again, and each change in this file is lost.
# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
# MISE description="Land a branch on main — merge it, or open a pull request"
# MISE tools={uv="latest", python="3.14", pre-commit="latest"}
# USAGE arg "[source]" help="the branch to merge into main; the default is develop when develop is a core branch, else the current branch"

# The sync writes this task only when main is in core_branches of
# `.config/bootstrap/repo.toml`. When develop is also there, develop is the
# source when you name no source. The library decides which source can merge
# in (`merge_from` of `[branches.main]`), and refuses a source equal to main.
#
# Under `landing = "pr"` of `[branches.main]`, the same pair becomes the
# request that this task opens.

import os
import subprocess
import sys

sys.dont_write_bytecode = True
sys.path.insert(0, f"{os.environ['MISE_PROJECT_ROOT']}/.config/mise/tasks/_scripts")
import helpers  # noqa: E402

# The import of merge does the check of the repository, before each other step.
import merge  # noqa: E402

# mise sets `usage_source` from the `# USAGE arg` above.
SOURCE = os.environ.get("usage_source", "")
if not SOURCE:
  CORE = helpers.bootstrap_get("repo.core_branches")
  value = CORE.get("value") if isinstance(CORE, dict) else None
  if value is None or value is False:
    value = []
  if not isinstance(value, list):
    helpers.print_error("cannot read core_branches of .config/bootstrap/repo.toml.")
    sys.exit(1)
  if "develop" in value:
    SOURCE = "develop"
  else:
    result = subprocess.run(
      ["git", "rev-parse", "--abbrev-ref", "HEAD"], check=False, stdout=subprocess.PIPE, text=True
    )
    if result.returncode != 0:
      sys.exit(result.returncode)
    SOURCE = result.stdout.rstrip("\n")

merge.merge_to_destination_branch("main", SOURCE)
